def first_duplicate(values):
    first_occurrence = {}
    earliest_second = None
    answer = None
    for i, v in enumerate(values):
        if v in first_occurrence:
            if earliest_second is None:
                earliest_second = i
                answer = v
            else:
                if i < earliest_second:
                    earliest_second = i
                    answer = v
        else:
            first_occurrence[v] = i
    return answer if earliest_second is not None else None
